using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Sandbox.CharacterSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FinishLioraShadingRepair {
