 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string data="Data/Liora/ShadingRepair/";if(!(bool)JObject.Parse(File.ReadAllText(data+"verification.json"))["passed"])throw new Exception("Shading preservation failed");
 var prefab=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");try{var face=prefab.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var rendererCount=prefab.GetComponentsInChildren<SkinnedMeshRenderer>(true).Length;if(rendererCount!=2||prefab.GetComponentsInChildren<Transform>(true).Any(t=>t.name.StartsWith("BAKED_",StringComparison.OrdinalIgnoreCase)))throw new Exception("Consolidated hierarchy regressed");
